package it.financemanager.infrastructure.persistence;
import it.financemanager.category.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class CategoryPersistenceAdapter implements CategoryStore { private final JpaCategoryRepository repository; CategoryPersistenceAdapter(JpaCategoryRepository repository){this.repository=repository;} public List<Category> findAllByUserIdOrderByNameAsc(Long userId){return repository.findAllByUserIdOrderByNameAsc(userId);} public Optional<Category> findByIdAndUserId(Long id,Long userId){return repository.findByIdAndUserId(id,userId);} public boolean existsByUserIdAndNameIgnoreCase(Long userId,String name){return repository.existsByUserIdAndNameIgnoreCase(userId,name);} public Category saveAndFlush(Category value){return repository.saveAndFlush(value);} public void delete(Category value){repository.delete(value);} public void flush(){repository.flush();} }
